package tn.gov.onpf.exception;
import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { private ResponseEntity<Map<String,String>> error(HttpStatus s,String m){return ResponseEntity.status(s).body(Collections.singletonMap("message",m));}@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) public ResponseEntity<Map<String,String>> bad(RuntimeException e){return error(HttpStatus.BAD_REQUEST,e.getMessage());}@ExceptionHandler(NoSuchElementException.class) public ResponseEntity<Map<String,String>> missing(NoSuchElementException e){return error(HttpStatus.NOT_FOUND,e.getMessage());}@ExceptionHandler(AccessDeniedException.class) public ResponseEntity<Map<String,String>> forbidden(AccessDeniedException e){return error(HttpStatus.FORBIDDEN,"ليس لديك الصلاحيات اللازمة للقيام بهذه العملية.");}@ExceptionHandler(ResponseStatusException.class) public ResponseEntity<Map<String,String>> responseStatus(ResponseStatusException e){HttpStatus status=HttpStatus.valueOf(e.getStatus().value());return error(status,e.getReason());}@ExceptionHandler(Exception.class) public ResponseEntity<Map<String,String>> other(Exception e){return error(HttpStatus.INTERNAL_SERVER_ERROR,"حدث خطأ أثناء الاتصال بالخادم.");} }
